<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api.js'
import { auth } from '../state.js'
const router = useRouter(), full_name = ref(''), email = ref(''), password = ref(''), loading = ref(false), error = ref('')
async function submit() { loading.value = true; error.value = ''; try { auth.user = (await api.register({ full_name: full_name.value, email: email.value, password: password.value })).user; auth.checked = true; router.push('/dashboard') } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
<template><div class="auth-layout"><section class="auth-brand-side"><div class="brand brand-on-dark"><span class="brand-icon">E</span><span>Exam<span class="brand-light">wise</span><small>EXAMINATION MANAGEMENT</small></span></div><div class="auth-message"><div class="eyebrow">Your academic journey</div><h1>Assessment,<br>made more human.</h1><p>Create your student account to discover examinations and keep your progress in one place.</p></div></section><section class="auth-form-side"><div class="auth-card"><div class="eyebrow">GET STARTED</div><h2>Create your account</h2><p class="muted">Student registration takes less than a minute.</p><form @submit.prevent="submit"><label>Full name</label><input v-model="full_name" required minlength="2" autocomplete="name" placeholder="Your name"><label>Email address</label><input v-model="email" required type="email" autocomplete="email" placeholder="you@university.edu"><label>Password</label><input v-model="password" required type="password" minlength="10" autocomplete="new-password" placeholder="At least 10 characters"><div v-if="error" class="alert alert-danger py-2">{{ error }}</div><button class="btn btn-primary w-100 mt-3" :disabled="loading">{{ loading ? 'Creating account…' : 'Create account' }} <span>→</span></button></form><div class="auth-switch">Already have an account? <RouterLink to="/login">Sign in</RouterLink></div></div></section></div></template>
